  if (noteToggle) noteToggle.setAttribute('data-internal-toggle', '');
  var send = button({ variant: 'primary', size: 'sm', icon: 'send', label: t(opts.sendLabel || 'tk.send'), onclick: function () { submit(); } });
  send.setAttribute('data-send', '');
