  var box = h('div', { 'data-referral-top': '' }, h('div', { class: 'eco-stat-grid mb-4' }, [1, 2, 3, 4].map(function () { return card(h('div', { class: 'p-4 flex flex-col gap-3' }, bar('6rem'), bar('3rem', 'h-7'))); })));
